INSERT INTO `jobs` (`id`, `title`, `department`, `organization_name`, `category`, `category_id`, `employer_id`, `employer_name`, `employer_type`, `job_type`, `work_setup`, `verified_employer`, `location`, `pay_rate`, `pay_type`, `hours_per_week`, `vacancies`, `slots_total`, `slots_filled`, `deadline`, `status`, `image`, `tags`, `badges`, `description`, `responsibilities`, `qualifications`, `created_at`, `updated_at`) VALUES (1, 'Computer Lab Technical Assistant', 'Management Information Systems (MIS)', 'Management Information Systems (MIS)', 'IT & Technical Support', 1, 4, 'Engr. Clara Villanueva', 'university_office', 'Student Assistant', 'On-Campus', 1, 'Main Campus · ICT Center 302', '₱85.00 / hour', 'Hourly', '15 - 20 hrs/week', 5, 5, 3, '2026-11-15', 'active', 'https://images.unsplash.com/photo-1531482615713-2afd69097998?q=80&w=900&auto=format&fit=crop', '[\"Flexible Schedule\",\"Urgent\",\"Tech Support\",\"University Office\"]', '[\"Student Assistant\",\"Flexible Schedule\",\"Urgent\"]', 'Assist the MIS team in maintaining student computer laboratories, performing routine hardware/software troubleshooting, monitoring laboratory usage, and assisting students during hands-on classes.', '[\"Check PC hardware and peripheral operability before daily lab sessions.\",\"Assist students and professors with network login, compiler installations, and software tools.\",\"Maintain cleanliness and enforce lab safety regulations.\",\"Log hardware faults and escalate critical network disruptions to senior network engineers.\"]', '[\"Currently enrolled 2nd to 4th year BSIS, BSCS, or BSDS student.\",\"General Weighted Average (GWA) of 2.25 or better.\",\"Basic knowledge in PC troubleshooting, Windows\\/Linux OS, and local networking.\",\"Responsible, punctual, and equipped with strong interpersonal skills.\"]', '2026-08-20 00:00:00', '2026-09-03 07:53:52') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `jobs` (`id`, `title`, `department`, `organization_name`, `category`, `category_id`, `employer_id`, `employer_name`, `employer_type`, `job_type`, `work_setup`, `verified_employer`, `location`, `pay_rate`, `pay_type`, `hours_per_week`, `vacancies`, `slots_total`, `slots_filled`, `deadline`, `status`, `image`, `tags`, `badges`, `description`, `responsibilities`, `qualifications`, `created_at`, `updated_at`) VALUES (2, 'Student Records & Archival Assistant', 'Office of the University Registrar', 'Office of the University Registrar', 'Administrative Clerk', 3, 3, 'Prof. Roberto Hernandez', 'university_office', 'Student Assistant', 'On-Campus', 1, 'Admin Building · Room 104', '₱80.00 / hour', 'Hourly', '10 - 15 hrs/week', 4, 4, 2, '2026-11-20', 'active', 'https://images.unsplash.com/photo-1497215728101-856f4ea42174?q=80&w=900&auto=format&fit=crop', '[\"Part-Time\",\"Office Work\",\"University Office\"]', '[\"Student Assistant\",\"Part-time\"]', 'Support the University Registrar in organizing student records, encoding registration documents, sorting physical course binders, and assisting visitors at the information desk.', '[\"Scan and index student transcript documents into the digital archive.\",\"Assist in receiving and sorting incoming student clearance and graduation applications.\",\"Organize student physical 201 filing cabinets.\",\"Provide courteous frontline queue direction during peak enrollment periods.\"]', '[\"Open to all undergraduate programs in good standing.\",\"Proficient in Microsoft Excel, Word, and Google Workspace.\",\"High attention to detail and strong adherence to data privacy and confidentiality.\",\"Must have at least 3 consecutive free hours during weekdays.\"]', '2026-08-21 00:00:00', '2026-09-03 07:53:52') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `jobs` (`id`, `title`, `department`, `organization_name`, `category`, `category_id`, `employer_id`, `employer_name`, `employer_type`, `job_type`, `work_setup`, `verified_employer`, `location`, `pay_rate`, `pay_type`, `hours_per_week`, `vacancies`, `slots_total`, `slots_filled`, `deadline`, `status`, `image`, `tags`, `badges`, `description`, `responsibilities`, `qualifications`, `created_at`, `updated_at`) VALUES (3, 'Digital Cataloging & Library Aid', 'University Library Services', 'KLD University Library', 'Library Services', 2, 3, 'Ms. Teresa Cruz (Chief Librarian)', 'university_office', 'Student Assistant', 'On-Campus', 1, 'Library Wing · 2nd Floor', '₱80.00 / hour', 'Hourly', '12 - 18 hrs/week', 3, 3, 1, '2026-11-25', 'active', 'https://images.unsplash.com/photo-1521587760476-6c12a4b040da?q=80&w=900&auto=format&fit=crop', '[\"Quiet Environment\",\"Study Friendly\",\"University Office\"]', '[\"Student Assistant\",\"Flexible Schedule\"]', 'Assist librarians with book circulation, Dewey Decimal sorting, barcode scanning, thesis collection archiving, and patron assistance in the quiet study hub.', '[\"Check in and check out library reference books using the barcode circulation scanner.\",\"Shelve books according to cataloging standards and perform shelf-reading.\",\"Assist students and faculty in navigating OPAC (Online Public Access Catalog).\",\"Monitor study areas to ensure a conducive, quiet learning atmosphere.\"]', '[\"Bona fide student with at least 1 remaining academic year.\",\"Diligent, polite, organized, and fond of reading and books.\",\"Can commit to either morning (8:00 AM - 12:00 PM) or afternoon (1:00 PM - 5:00 PM) shifts.\"]', '2026-08-22 00:00:00', '2026-09-03 07:53:52') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `jobs` (`id`, `title`, `department`, `organization_name`, `category`, `category_id`, `employer_id`, `employer_name`, `employer_type`, `job_type`, `work_setup`, `verified_employer`, `location`, `pay_rate`, `pay_type`, `hours_per_week`, `vacancies`, `slots_total`, `slots_filled`, `deadline`, `status`, `image`, `tags`, `badges`, `description`, `responsibilities`, `qualifications`, `created_at`, `updated_at`) VALUES (4, 'Peer Tutor - Linear Algebra & Discrete Math', 'Institute of Science and Mathematics (ISM)', 'Institute of Science and Mathematics (ISM)', 'Peer Tutor', 5, 4, 'Dr. Antonio Valderama', 'university_office', 'Peer Tutor', 'On-Campus', 1, 'Learning Commons · Room 204', '₱100.00 / hour', 'Hourly', '8 - 12 hrs/week', 2, 2, 1, '2026-12-05', 'active', 'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?q=80&w=900&auto=format&fit=crop', '[\"High Pay\",\"Academic\",\"Peer Tutor\"]', '[\"Peer Tutor\",\"Part-time\",\"Flexible Schedule\"]', 'Provide scheduled one-on-one and small group peer tutoring for 1st and 2nd year students struggling with Linear Algebra, Discrete Mathematics, and Calculus.', '[\"Conduct structured 1-hour tutorial sessions according to student bookings.\",\"Prepare sample problem worksheets and concept explanation summaries.\",\"Maintain student attendance logs and report progress to the Department Chair.\",\"Encourage active problem solving and confidence building.\"]', '[\"Currently enrolled in BSCS, BSIS, BSDS, or BSCE.\",\"Must have earned a final grade of 1.50 or higher in Linear Algebra and Discrete Math.\",\"Patient, articulate, and passionate about teaching math concepts.\",\"Endorsement letter from an ISM faculty member is a plus.\"]', '2026-08-23 00:00:00', '2026-09-03 07:53:52') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `jobs` (`id`, `title`, `department`, `organization_name`, `category`, `category_id`, `employer_id`, `employer_name`, `employer_type`, `job_type`, `work_setup`, `verified_employer`, `location`, `pay_rate`, `pay_type`, `hours_per_week`, `vacancies`, `slots_total`, `slots_filled`, `deadline`, `status`, `image`, `tags`, `badges`, `description`, `responsibilities`, `qualifications`, `created_at`, `updated_at`) VALUES (5, 'Junior Web Developer Intern (OJT)', 'Software & Web Development Partner', 'TechVanguard Solutions Inc.', 'IT & Technical Support', 1, 6, 'Atty. Katrina Alcantara', 'approved_partner', 'Internship / OJT', 'Hybrid', 1, 'Dasma Tech Park / Hybrid (Near Campus)', '₱120.00 / hour', 'Hourly', '15 - 20 hrs/week', 3, 3, 1, '2026-12-12', 'active', 'https://images.unsplash.com/photo-1498050108023-c5249f4df085?q=80&w=900&auto=format&fit=crop', '[\"Internship\",\"Web Dev\",\"Approved Partner\",\"High Pay\"]', '[\"Internship \\/ OJT\",\"Approved Partner\",\"Hybrid\"]', 'Join an accredited industry technology partner to develop real-world client web applications using HTML/CSS, JavaScript, PHP/Node, and modern API integrations. Perfect for 3rd and 4th year computing students seeking academic OJT credits.', '[\"Collaborate with lead developers in building responsive UI layouts and backend APIs.\",\"Participate in daily agile sprint standups and code reviews.\",\"Debug cross-browser frontend issues and write clean, modular documentation.\",\"Submit weekly supervisor evaluations for college OJT accreditation.\"]', '[\"Currently enrolled in BSIS, BSCS, or related technical degrees.\",\"Familiar with Git, JavaScript, PHP, and responsive CSS frameworks.\",\"Able to commit 15\\u201320 hours\\/week in a hybrid setup (2 days on-site, 2 days remote).\",\"Official endorsement form from the KLD Practicum Coordinator.\"]', '2026-08-24 00:00:00', '2026-09-03 07:53:52') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `jobs` (`id`, `title`, `department`, `organization_name`, `category`, `category_id`, `employer_id`, `employer_name`, `employer_type`, `job_type`, `work_setup`, `verified_employer`, `location`, `pay_rate`, `pay_type`, `hours_per_week`, `vacancies`, `slots_total`, `slots_filled`, `deadline`, `status`, `image`, `tags`, `badges`, `description`, `responsibilities`, `qualifications`, `created_at`, `updated_at`) VALUES (6, 'Part-Time Social Media & Content Creator', 'Creative & Digital Media Partner', 'Dasma Creative Media Studio', 'Administrative Clerk', 3, 7, 'Marco V. Domingo', 'approved_partner', 'Part-Time Job', 'Near-Campus', 1, 'Creative Hub Center (Near Campus)', '₱110.00 / hour', 'Hourly', '12 - 16 hrs/week', 2, 2, 0, '2026-12-18', 'active', 'https://images.unsplash.com/photo-1542744094-3a31f272c490?q=80&w=900&auto=format&fit=crop', '[\"Part-Time\",\"Creative\",\"Approved Partner\"]', '[\"Part-Time Job\",\"Approved Partner\",\"Creative\"]', 'Create engaging short-form TikTok/Reels video content, design Canva graphics for local marketing campaigns, and assist in copywriting for an approved regional media partner.', '[\"Shoot and edit engaging vertical video content highlighting youth lifestyle and education.\",\"Design branded social media post carousels and promotional posters.\",\"Monitor engagement metrics and respond to community comments under guidance.\",\"Ensure all published material adheres to university partner ethical standards.\"]', '[\"Passionate about video editing (CapCut, Premiere, or Canva).\",\"Creative eye for typography, layouts, and storytelling.\",\"Flexible schedule tailored around class timetables.\"]', '2026-08-25 00:00:00', '2026-09-03 07:53:52') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `jobs` (`id`, `title`, `department`, `organization_name`, `category`, `category_id`, `employer_id`, `employer_name`, `employer_type`, `job_type`, `work_setup`, `verified_employer`, `location`, `pay_rate`, `pay_type`, `hours_per_week`, `vacancies`, `slots_total`, `slots_filled`, `deadline`, `status`, `image`, `tags`, `badges`, `description`, `responsibilities`, `qualifications`, `created_at`, `updated_at`) VALUES (7, 'Student Barista & Customer Service Crew', 'Campus Food Concessionaire Partner', 'Campus Cafe & Co.', 'Administrative Clerk', 3, 8, 'Chef Patricia Reyes', 'approved_partner', 'Part-Time Job', 'On-Campus', 1, 'University Student Pavilion & Food Arcade', '₱90.00 / hour', 'Hourly', '10 - 15 hrs/week', 3, 3, 1, '2026-12-20', 'active', 'https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?q=80&w=900&auto=format&fit=crop', '[\"Part-Time\",\"Customer Service\",\"On-Campus\"]', '[\"Part-Time Job\",\"On-Campus\",\"Flexible Schedule\"]', 'Learn specialty espresso brewing, assist in counter POS cashiering, and provide friendly hospitality at the official campus student cafe located inside the Student Pavilion.', '[\"Prepare espresso drinks, cold brews, and seasonal refreshments following recipes.\",\"Operate touch-screen point-of-sale register and issue official receipts.\",\"Maintain strict cleanliness and food safety sanitation in the dining area.\",\"Coordinate with supervisor for weekly shift planning aligned with class schedules.\"]', '[\"Cheerful, friendly demeanor with strong work ethic.\",\"No prior barista experience required; complete paid on-site training provided.\",\"Available for morning (7:30 AM - 11:30 AM) or afternoon (1:30 PM - 5:30 PM) slots.\"]', '2026-08-26 00:00:00', '2026-09-03 07:53:52') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `jobs` (`id`, `title`, `department`, `organization_name`, `category`, `category_id`, `employer_id`, `employer_name`, `employer_type`, `job_type`, `work_setup`, `verified_employer`, `location`, `pay_rate`, `pay_type`, `hours_per_week`, `vacancies`, `slots_total`, `slots_filled`, `deadline`, `status`, `image`, `tags`, `badges`, `description`, `responsibilities`, `qualifications`, `created_at`, `updated_at`) VALUES (8, 'Science & Computer Lab Assistant', 'College of Science & Laboratories', 'College of Science & Laboratories', 'Science & Computer Lab Assistant', 4, 5, 'Lab Head Dr. Reyes', 'university_office', 'Student Assistant', 'On-Campus', 1, 'Science Wing · Lab 101', '₱85.00 / hour', 'Hourly', '12 - 16 hrs/week', 4, 4, 2, '2026-12-10', 'active', 'https://images.unsplash.com/photo-1582719471384-894fbb16e074?q=80&w=900&auto=format&fit=crop', '[\"Science\",\"Lab Prep\",\"University Office\"]', '[\"Student Assistant\",\"Urgent\"]', 'Assist laboratory custodians in preparing glassware, non-hazardous reagent solutions, setting up microscope benches, and conducting equipment sanitation.', '[\"Distribute apparatus to students before experiments and inspect returns for breakage.\",\"Wash and autoclave laboratory glassware following strict chemical hygiene procedures.\",\"Maintain reagent inventory and log chemical consumption.\",\"Ensure proper waste segregation and disposal compliance.\"]', '[\"Enrolled in Allied Science, Computer, or Engineering programs.\",\"Passed Chemistry\\/Lab fundamentals with high marks.\",\"Strict compliance with lab safety goggles, lab coat, and chemical handling guidelines.\"]', '2026-08-25 00:00:00', '2026-09-03 07:53:52') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
